    for (let i = 0; i < agentCount; i++) {
      const currentAgent = agents[i];
      enrichedAgents[i] = {
        ...currentAgent,
        vote: voteMap.get(currentAgent.id)
      };
    }

    return enrichedAgents;
  }, [agents, votes]);

