        <div
          className="px-3 py-2 rounded text-center"
          style={{ background: '#060606' }}
        >
          <p style={{ fontSize: '10px', color: COLORS.textMuted }}>
            No active debate. Initiate analysis to convene the chamber.
          </p>
        </div>
      )}
    </div>
