                  border: `1px solid ${mode === 'debate' ? `${COLORS.purple}40` : COLORS.panelBorder}`,
                  borderRadius: '2px',
                  boxShadow: mode === 'debate' ? `0 0 8px ${COLORS.purple}15` : 'none',
