                      }}
                    >
                      {r}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Topic input */}
            <div>
              <div
                className="mb-1.5"
                style={{
                  fontFamily: 'var(--font-orbitron), sans-serif',
                  fontSize: '8px',
                  letterSpacing: '0.08em',
                  color: COLORS.textMuted,
                }}
